package sandbox

import (
	"testing"
)

func TestReverse(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "empty string",
			input:    "",
			expected: "",
		},
		{
			name:     "single rune",
			input:    "a",
			expected: "a",
		},
		{
			name:     "ASCII string",
			input:    "hello",
			expected: "olleh",
		},
		{
			name:     "Unicode mixed",
			input:    "héllo wörld",
			expected: "dlröw olléh",
		},
		{
			name:     "emoji",
			input:    "😀😃😄",
			expected: "😄😃😀",
		},
		{
			name:     "mixed Unicode",
			input:    "café résumé",
			expected: "émusér éfac",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := Reverse(tt.input)
			if result != tt.expected {
				t.Errorf("Reverse(%q) = %q, want %q", tt.input, result, tt.expected)
			}
		})
	}
}

package sandbox

import (
	"strings"
	"testing"
)

func WordCount(s string) map[string]int {
	fields := strings.Fields(s)
	counts := make(map[string]int)
	for _, field := range fields {
		counts[field]++
	}
	return counts
}

func TestWordCount(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  map[string]int
	}{
		{
			name:  "empty string",
			input: "",
			want:  map[string]int{},
		},
		{
			name:  "single word",
			input: "hello",
			want:  map[string]int{"hello": 1},
		},
		{
			name:  "multiple words",
			input: "hello world hello",
			want:  map[string]int{"hello": 2, "world": 1},
		},
		{
			name:  "whitespace variations",
			input: "  hello   world  \n\t hello  ",
			want:  map[string]int{"hello": 2, "world": 1},
		},
		{
			name:  "empty and whitespace",
			input: "   \t\n  ",
			want:  map[string]int{},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := WordCount(tt.input)
			if len(got) != len(tt.want) {
				t.Errorf("WordCount() got %d items, want %d", len(got), len(tt.want))
				return
			}
			for key, value := range tt.want {
				if got[key] != value {
					t.Errorf("WordCount() got[%q] = %d, want %d", key, got[key], value)
				}
			}
		})
	}
}

package sandbox

import (
	"reflect"
	"testing"
)

func TestDedup(t *testing.T) {
	tests := []struct {
		name string
		in   []int
		want []int
	}{
		{
			name: "empty slice",
			in:   []int{},
			want: []int{},
		},
		{
			name: "single element",
			in:   []int{1},
			want: []int{1},
		},
		{
			name: "no duplicates",
			in:   []int{1, 2, 3, 4, 5},
			want: []int{1, 2, 3, 4, 5},
		},
		{
			name: "all duplicates",
			in:   []int{1, 1, 1, 1},
			want: []int{1},
		},
		{
			name: "mixed duplicates",
			in:   []int{1, 2, 1, 3, 2, 4},
			want: []int{1, 2, 3, 4},
		},
		{
			name: "duplicates at end",
			in:   []int{1, 2, 3, 4, 4, 3, 2, 1},
			want: []int{1, 2, 3, 4},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Dedup(tt.in)
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("Dedup() = %v, want %v", got, tt.want)
			}
		})
	}
}

package sandbox

import (
	"testing"
)

func TestIsPalindrome(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected bool
	}{
		{
			name:     "empty string",
			input:    "",
			expected: true,
		},
		{
			name:     "single character",
			input:    "a",
			expected: true,
		},
		{
			name:     "simple palindrome",
			input:    "aba",
			expected: true,
		},
		{
			name:     "case insensitive",
			input:    "Aba",
			expected: true,
		},
		{
			name:     "with numbers",
			input:    "a1b1a",
			expected: true,
		},
		{
			name:     "mixed case and numbers",
			input:    "A1B2b1a",
			expected: true,
		},
		{
			name:     "not a palindrome",
			input:    "abc",
			expected: false,
		},
		{
			name:     "with special characters",
			input:    "a!b@a",
			expected: true,
		},
		{
			name:     "complex palindrome",
			input:    "A man, a plan, a canal: Panama",
			expected: true,
		},
		{
			name:     "complex not palindrome",
			input:    "race a car",
			expected: false,
		},
		{
			name:     "only special characters",
			input:    "!@#$%",
			expected: true,
		},
		{
			name:     "numbers only",
			input:    "12321",
			expected: true,
		},
		{
			name:     "numbers not palindrome",
			input:    "12345",
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := IsPalindrome(tt.input)
			if result != tt.expected {
				t.Errorf("IsPalindrome(%q) = %v, want %v", tt.input, result, tt.expected)
			}
		})
	}
}

package sandbox

import "testing"

func Map[T, U any](s []T, f func(T) U) []U {
	if s == nil {
		return nil
	}
	result := make([]U, len(s))
	for i, v := range s {
		result[i] = f(v)
	}
	return result
}

func TestMap(t *testing.T) {
	// Test with empty slice
	result := Map[int, int]([]int{}, func(x int) int { return x * 2 })
	if len(result) != 0 {
		t.Errorf("Expected empty slice, got length %d", len(result))
	}

	// Test with integers
	input := []int{1, 2, 3, 4}
	result = Map(input, func(x int) int { return x * 2 })
	expected := []int{2, 4, 6, 8}
	for i, v := range expected {
		if result[i] != v {
			t.Errorf("At index %d: expected %d, got %d", i, v, result[i])
		}
	}

	// Test with strings
	inputStr := []string{"a", "b", "c"}
	resultStr := Map(inputStr, func(s string) string { return s + "x" })
	expectedStr := []string{"ax", "bx", "cx"}
	for i, v := range expectedStr {
		if resultStr[i] != v {
			t.Errorf("At index %d: expected %s, got %s", i, v, resultStr[i])
		}
	}

	// Test with nil slice
	var nilSlice []int
	resultNil := Map(nilSlice, func(x int) int { return x * 2 })
	if resultNil != nil {
		t.Errorf("Expected nil result for nil input, got %v", resultNil)
	}
}

package sandbox

import (
	"errors"
	"testing"
)

func TestParsePort(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		want    int
		wantErr error
	}{
		{
			name:    "valid port 80",
			input:   "80",
			want:    80,
			wantErr: nil,
		},
		{
			name:    "valid port 65535",
			input:   "65535",
			want:    65535,
			wantErr: nil,
		},
		{
			name:    "valid port 1",
			input:   "1",
			want:    1,
			wantErr: nil,
		},
		{
			name:    "invalid port -1",
			input:   "-1",
			want:    0,
			wantErr: ErrBadPort,
		},
		{
			name:    "invalid port 65536",
			input:   "65536",
			want:    0,
			wantErr: ErrBadPort,
		},
		{
			name:    "invalid port non-numeric",
			input:   "abc",
			want:    0,
			wantErr: ErrBadPort,
		},
		{
			name:    "invalid port empty string",
			input:   "",
			want:    0,
			wantErr: ErrBadPort,
		},
		{
			name:    "invalid port with whitespace",
			input:   " 80 ",
			want:    0,
			wantErr: ErrBadPort,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParsePort(tt.input)
			if got != tt.want {
				t.Errorf("ParsePort(%q) = %v, want %v", tt.input, got, tt.want)
			}
			if !errors.Is(err, tt.wantErr) {
				t.Errorf("ParsePort(%q) error = %v, wantErr %v", tt.input, err, tt.wantErr)
			}
		})
	}
}

package sandbox

import (
	"sync"
	"testing"
)

func TestCounterInc(t *testing.T) {
	c := &Counter{}
	c.Inc("key1")
	c.Inc("key1")
	c.Inc("key2")

	if got := c.Get("key1"); got != 2 {
		t.Errorf("Expected key1 to have value 2, got %d", got)
	}

	if got := c.Get("key2"); got != 1 {
		t.Errorf("Expected key2 to have value 1, got %d", got)
	}
}

func TestCounterGet(t *testing.T) {
	c := &Counter{}

	if got := c.Get("nonexistent"); got != 0 {
		t.Errorf("Expected nonexistent key to return 0, got %d", got)
	}

	c.Inc("test")
	if got := c.Get("test"); got != 1 {
		t.Errorf("Expected test key to have value 1, got %d", got)
	}
}

func TestCounterConcurrent(t *testing.T) {
	c := &Counter{}
	var wg sync.WaitGroup

	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 100; j++ {
				c.Inc("counter")
			}
		}()
	}

	wg.Wait()

	if got := c.Get("counter"); got != 10000 {
		t.Errorf("Expected counter to have value 10000, got %d", got)
	}
}

func TestCounterMultipleKeys(t *testing.T) {
	c := &Counter{}

	keys := []string{"a", "b", "c", "a", "b", "a"}

	for _, key := range keys {
		c.Inc(key)
	}

	if got := c.Get("a"); got != 3 {
		t.Errorf("Expected key 'a' to have value 3, got %d", got)
	}

	if got := c.Get("b"); got != 2 {
		t.Errorf("Expected key 'b' to have value 2, got %d", got)
	}

	if got := c.Get("c"); got != 1 {
		t.Errorf("Expected key 'c' to have value 1, got %d", got)
	}
}

package sandbox

import (
	"encoding/json"
	"testing"
)

type Point struct {
	X int `json:"x"`
	Y int `json:"y"`
}

func Encode(p Point) (string, error) {
	return json.Marshal(p)
}

func TestEncode(t *testing.T) {
	tests := []struct {
		name string
		p    Point
		want string
	}{
		{
			name: "zero point",
			p:    Point{0, 0},
			want: `{"x":0,"y":0}`,
		},
		{
			name: "positive coordinates",
			p:    Point{1, 2},
			want: `{"x":1,"y":2}`,
		},
		{
			name: "negative coordinates",
			p:    Point{-1, -2},
			want: `{"x":-1,"y":-2}`,
		},
		{
			name: "mixed coordinates",
			p:    Point{5, -3},
			want: `{"x":5,"y":-3}`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Encode(tt.p)
			if err != nil {
				t.Errorf("Encode() error = %v", err)
				return
			}
			if got != tt.want {
				t.Errorf("Encode() = %v, want %v", got, tt.want)
			}
		})
	}
}

package sandbox

import (
	"sort"
	"testing"
)

func SortByLen(ss []string) {
	sort.SliceStable(ss, func(i, j int) bool {
		return len(ss[i]) < len(ss[j])
	})
}

func TestSortByLen(t *testing.T) {
	// Test empty slice
	ss := []string{}
	SortByLen(ss)
	if len(ss) != 0 {
		t.Errorf("Expected empty slice, got %v", ss)
	}

	// Test single element
	ss = []string{"hello"}
	SortByLen(ss)
	if len(ss) != 1 || ss[0] != "hello" {
		t.Errorf("Expected [\"hello\"], got %v", ss)
	}

	// Test multiple elements with same length
	ss = []string{"cat", "dog", "bat"}
	SortByLen(ss)
	expected := []string{"cat", "dog", "bat"}
	for i, v := range expected {
		if ss[i] != v {
			t.Errorf("Expected %v, got %v", expected, ss)
		}
	}

	// Test elements with different lengths
	ss = []string{"hello", "hi", "world", "a", "test"}
	SortByLen(ss)
	expected = []string{"a", "hi", "test", "hello", "world"}
	for i, v := range expected {
		if ss[i] != v {
			t.Errorf("Expected %v, got %v", expected, ss)
		}
	}

	// Test already sorted
	ss = []string{"a", "bb", "ccc"}
	SortByLen(ss)
	expected = []string{"a", "bb", "ccc"}
	for i, v := range expected {
		if ss[i] != v {
			t.Errorf("Expected %v, got %v", expected, ss)
		}
	}

	// Test reverse sorted
	ss = []string{"ccc", "bb", "a"}
	SortByLen(ss)
	expected = []string{"a", "bb", "ccc"}
	for i, v := range expected {
		if ss[i] != v {
			t.Errorf("Expected %v, got %v", expected, ss)
		}
	}
}

package sandbox

import (
	"reflect"
	"testing"
)

func TestChunk(t *testing.T) {
	// Test empty slice
	result := Chunk([]int{}, 1)
	expected := [][]int{}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]int{}, 1) = %v, want %v", result, expected)
	}

	// Test chunk size larger than slice
	result = Chunk([]int{1, 2, 3}, 5)
	expected = [][]int{{1, 2, 3}}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]int{1, 2, 3}, 5) = %v, want %v", result, expected)
	}

	// Test exact division
	result = Chunk([]int{1, 2, 3, 4}, 2)
	expected = [][]int{{1, 2}, {3, 4}}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]int{1, 2, 3, 4}, 2) = %v, want %v", result, expected)
	}

	// Test remainder
	result = Chunk([]int{1, 2, 3, 4, 5}, 2)
	expected = [][]int{{1, 2}, {3, 4}, {5}}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]int{1, 2, 3, 4, 5}, 2) = %v, want %v", result, expected)
	}

	// Test single element
	result = Chunk([]string{"a"}, 1)
	expected = [][]string{{"a"}}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]string{\"a\"}, 1) = %v, want %v", result, expected)
	}

	// Test with strings
	result = Chunk([]string{"a", "b", "c", "d"}, 3)
	expected = [][]string{{"a", "b", "c"}, {"d"}}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]string{\"a\", \"b\", \"c\", \"d\"}, 3) = %v, want %v", result, expected)
	}

	// Test chunk size of 1
	result = Chunk([]int{1, 2, 3}, 1)
	expected = [][]int{{1}, {2}, {3}}
	if !reflect.DeepEqual(result, expected) {
		t.Errorf("Chunk([]int{1, 2, 3}, 1) = %v, want %v", result, expected)
	}
}

package sandbox

import (
	"testing"
)

func TestMax(t *testing.T) {
	// Test with empty input
	if _, ok := Max[int](); ok {
		t.Error("Expected false for empty input")
	}

	// Test with single element
	if max, ok := Max[int](5); !ok || max != 5 {
		t.Error("Expected 5 for single element input")
	}

	// Test with multiple integers
	if max, ok := Max[int](1, 2, 3, 4, 5); !ok || max != 5 {
		t.Error("Expected 5 for multiple integers")
	}

	// Test with negative numbers
	if max, ok := Max[int](-1, -2, -3); !ok || max != -1 {
		t.Error("Expected -1 for negative numbers")
	}

	// Test with mixed positive and negative
	if max, ok := Max[int](-5, 0, 5); !ok || max != 5 {
		t.Error("Expected 5 for mixed numbers")
	}

	// Test with int64
	if max, ok := Max[int64](1000000000000, 2000000000000); !ok || max != 2000000000000 {
		t.Error("Expected 2000000000000 for int64")
	}

	// Test with float64
	if max, ok := Max[float64](1.1, 2.2, 3.3); !ok || max != 3.3 {
		t.Error("Expected 3.3 for float64")
	}

	// Test with float64 negative
	if max, ok := Max[float64](-1.1, -2.2, -3.3); !ok || max != -1.1 {
		t.Error("Expected -1.1 for negative float64")
	}
}

