package sandbox

import "testing"

func TestGroupParity(t *testing.T) {
	tests := []struct {
		name string
		xs   []int
		want map[string][]int
	}{
		{
			name: "empty slice",
			xs:   []int{},
			want: map[string][]int{
				"even": []int{},
				"odd":  []int{},
			},
		},
		{
			name: "all even numbers",
			xs:   []int{2, 4, 6, 8},
			want: map[string][]int{
				"even": []int{2, 4, 6, 8},
				"odd":  []int{},
			},
		},
		{
			name: "all odd numbers",
			xs:   []int{1, 3, 5, 7},
			want: map[string][]int{
				"even": []int{},
				"odd":  []int{1, 3, 5, 7},
			},
		},
		{
			name: "mixed numbers",
			xs:   []int{1, 2, 3, 4, 5, 6},
			want: map[string][]int{
				"even": []int{2, 4, 6},
				"odd":  []int{1, 3, 5},
			},
		},
		{
			name: "negative numbers",
			xs:   []int{-1, -2, -3, -4},
			want: map[string][]int{
				"even": []int{-2, -4},
				"odd":  []int{-1, -3},
			},
		},
		{
			name: "zero included",
			xs:   []int{0, 1, 2, 3},
			want: map[string][]int{
				"even": []int{0, 2},
				"odd":  []int{1, 3},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := GroupParity(tt.xs)
			if len(got["even"]) != len(tt.want["even"]) {
				t.Errorf("GroupParity() even length = %v, want %v", len(got["even"]), len(tt.want["even"]))
			}
			for i, v := range got["even"] {
				if v != tt.want["even"][i] {
					t.Errorf("GroupParity() even[%v] = %v, want %v", i, v, tt.want["even"][i])
				}
			}
			if len(got["odd"]) != len(tt.want["odd"]) {
				t.Errorf("GroupParity() odd length = %v, want %v", len(got["odd"]), len(tt.want["odd"]))
			}
			for i, v := range got["odd"] {
				if v != tt.want["odd"][i] {
					t.Errorf("GroupParity() odd[%v] = %v, want %v", i, v, tt.want["odd"][i])
				}
			}
		})
	}
}

package sandbox

import (
	"testing"
)

func TestFlatten(t *testing.T) {
	tests := []struct {
		name string
		in   [][]int
		want []int
	}{
		{
			name: "empty slice",
			in:   [][]int{},
			want: []int{},
		},
		{
			name: "nil sub-slices",
			in:   [][]int{nil, nil},
			want: []int{},
		},
		{
			name: "mixed empty and non-empty",
			in:   [][]int{{}, {1, 2}, {}, {3, 4}},
			want: []int{1, 2, 3, 4},
		},
		{
			name: "single sub-slice",
			in:   [][]int{{1, 2, 3}},
			want: []int{1, 2, 3},
		},
		{
			name: "multiple sub-slices",
			in:   [][]int{{1}, {2}, {3}},
			want: []int{1, 2, 3},
		},
