			body:           `{"a": 1, "b": 2}`,
			expectedStatus: http.StatusOK,
			expectedBody:   `{"sum":3}`,
		},
		{
			name:           "negative numbers",
			body:           `{"a": -1, "b": 5}`,
			expectedStatus: http.StatusOK,
			expectedBody:   `{"sum":4}`,
		},
		{
			name:           "zero values",
			body:           `{"a": 0, "b": 0}`,
			expectedStatus: http.StatusOK,
			expectedBody:   `{"sum":0}`,
		},
		{
			name:           "malformed JSON",
			body:           `{"a": 1, "b":}`,
			expectedStatus: http.StatusBadRequest,
			expectedBody:   ``,
		},
		{
			name:           "missing fields",
			body:           `{"a": 1}`,
			expectedStatus: http.StatusBadRequest,
			expectedBody:   ``,
		},
		{
			name:           "extra fields",
			body:           `{"a": 1, "b": 2, "c": 3}`,
