import (
	"sort"
	"strings"
	"testing"
)

func TopK(s string, k int) []string {
	if s == "" || k <= 0 {
		return []string{}
	}

	// Count frequency of each word
	wordCount := make(map[string]int)
	words := strings.Fields(s)
	for _, word := range words {
		wordCount[word]++
	}

	// Create slice of unique words
	uniqueWords := make([]string, 0, len(wordCount))
	for word := range wordCount {
		uniqueWords = append(uniqueWords, word)
	}

	// Sort by frequency (descending) and then alphabetically (ascending)
	sort.Slice(uniqueWords, func(i, j int) bool {
		countI := wordCount[uniqueWords[i]]
		countJ := wordCount[uniqueWords[j]]
		if countI != countJ {
			return countI > countJ // Higher frequency first
		}
		return uniqueWords[i] < uniqueWords[j] // Alphabetical order
	})

	// Return top k words
	if k > len(uniqueWords) {
		k = len(uniqueWords)
	}
	return uniqueWords[:k]
}

func TestTopK(t *testing.T) {
	// Test empty string
	result := TopK("", 3)
	if len(result) != 0 {
		t.Errorf("Expected empty slice for empty input, got %v", result)
	}

	// Test k = 0
	result = TopK("hello world hello", 0)
	if len(result) != 0 {
		t.Errorf("Expected empty slice for k=0, got %v", result)
	}

	// Test basic functionality
	result = TopK("the quick brown fox jumps over the lazy dog the fox", 3)
	expected := []string{"the", "fox", "brown"}
	if len(result) != len(expected) {
		t.Errorf("Expected length %d, got %d", len(expected), len(result))
	}
	for i, exp := range expected {
		if result[i] != exp {
			t.Errorf("Expected %s at position %d, got %s", exp, i, result[i])
		}
	}

	// Test tie-breaking alphabetically
	result = TopK("cat dog bird cat dog", 2)
	expected = []string{"cat", "dog"}
	if len(result) != len(expected) {
		t.Errorf("Expected length %d, got %d", len(expected), len(result))
	}
	for i, exp := range expected {
		if result[i] != exp {
			t.Errorf("Expected %s at position %d, got %s", exp, i, result[i])
		}
	}

	// Test k larger than unique words
	result = TopK("hello world hello", 5)
	expected = []string{"hello", "world"}
	if len(result) != len(expected) {
		t.Errorf("Expected length %d, got %d", len(expected), len(result))
	}
	for i, exp := range expected {
		if result[i] != exp {
			t.Errorf("Expected %s at position %d, got %s", exp, i, result[i])
		}
	}

	// Test single word
	result = TopK("hello", 1)
	expected = []string{"hello"}
	if len(result) != len(expected) {
		t.Errorf("Expected length %d, got %d", len(expected), len(result))
	}
	for i, exp := range expected {
		if result[i] != exp {
			t.Errorf("Expected %s at position %d, got %s", exp, i, result[i])
		}
	}
}

