	Age  int
}

func SortPeople(p []Person) {
	sort.Slice(p, func(i, j int) bool {
		if p[i].Age == p[j].Age {
			return p[i].Name < p[j].Name
		}
		return p[i].Age < p[j].Age
	})
}

func TestSortPeople(t *testing.T) {
	tests := []struct {
		name     string
		input    []Person
		expected []Person
	}{
		{
			name:     "empty slice",
			input:    []Person{},
			expected: []Person{},
		},
		{
			name: "single person",
			input: []Person{
				{Name: "Alice", Age: 30},
			},
			expected: []Person{
				{Name: "Alice", Age: 30},
			},
		},
		{
			name: "sort by age ascending",
			input: []Person{
				{Name: "Charlie", Age: 35},
				{Name: "Alice", Age: 30},
				{Name: "Bob", Age: 25},
			},
			expected: []Person{
				{Name: "Bob", Age: 25},
				{Name: "Alice", Age: 30},
				{Name: "Charlie", Age: 35},
			},
		},
		{
			name: "sort by age ascending, then name ascending",
			input: []Person{
				{Name: "Charlie", Age: 30},
				{Name: "Alice", Age: 30},
				{Name: "Bob", Age: 25},
			},
			expected: []Person{
				{Name: "Bob", Age: 25},
				{Name: "Alice", Age: 30},
				{Name: "Charlie", Age: 30},
			},
		},
		{
			name: "already sorted",
			input: []Person{
				{Name: "Bob", Age: 25},
				{Name: "Alice", Age: 30},
				{Name: "Charlie", Age: 35},
			},
			expected: []Person{
				{Name: "Bob", Age: 25},
				{Name: "Alice", Age: 30},
				{Name: "Charlie", Age: 35},
