func CamelToSnake(s string) string {
	if s == "" {
		return ""
	}

	var result strings.Builder
	for i, char := range s {
		if char >= 'A' && char <= 'Z' {
			if i > 0 {
				result.WriteRune('_')
			}
			result.WriteRune(char + 'a' - 'A')
		} else {
			result.WriteRune(char)
		}
	}
	return result.String()
}

func TestCamelToSnake(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{
			name:  "empty string",
			input: "",
			want:  "",
		},
		{
			name:  "single lowercase",
			input: "a",
			want:  "a",
		},
		{
			name:  "single uppercase",
			input: "A",
			want:  "a",
		},
		{
			name:  "camelCase with one word",
			input: "camelCase",
			want:  "camel_case",
		},
		{
			name:  "camelCase with multiple words",
			input: "camelCaseString",
			want:  "camel_case_string",
		},
		{
			name:  "all uppercase",
			input: "XMLHttpRequest",
			want:  "xml_http_request",
		},
		{
			name:  "already snake_case",
			input: "snake_case_string",
			want:  "snake_case_string",
		},
		{
			name:  "mixed case",
			input: "getHTTPResponseCode",
			want:  "get_http_response_code",
		},
		{
			name:  "numbers",
			input: "version2Test",
			want:  "version2_test",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := CamelToSnake(tt.input); got != tt.want {
				t.Errorf("CamelToSnake(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}

