// NotFoundError represents an error with a specific code for not found cases
type NotFoundError struct {
	Code int
}

// Error returns the string representation of the NotFoundError
func (e *NotFoundError) Error() string {
	return fmt.Sprintf("not found: code %d", e.Code)
}

// CodeOf extracts the Code from a NotFoundError anywhere in the error chain
// Returns -1 if no NotFoundError is found in the chain
func CodeOf(err error) int {
	var notFoundErr *NotFoundError
	if errors.As(err, &notFoundErr) {
		return notFoundErr.Code
	}
	return -1
}

// TestNotFoundError tests the NotFoundError implementation
func TestNotFoundError(t *testing.T) {
	err := &NotFoundError{Code: 42}
	if err.Error() != "not found: code 42" {
		t.Errorf("Expected 'not found: code 42', got %q", err.Error())
	}
}

// TestCodeOf tests the CodeOf function with various error scenarios
func TestCodeOf(t *testing.T) {
	// Test with nil error
	if CodeOf(nil) != -1 {
		t.Errorf("Expected -1 for nil error, got %d", CodeOf(nil))
	}

	// Test with direct NotFoundError
	notFound := &NotFoundError{Code: 123}
	if CodeOf(notFound) != 123 {
		t.Errorf("Expected 123, got %d", CodeOf(notFound))
	}

	// Test with wrapped NotFoundError
	wrapped := fmt.Errorf("wrapped: %w", notFound)
	if CodeOf(wrapped) != 123 {
		t.Errorf("Expected 123 from wrapped error, got %d", CodeOf(wrapped))
	}

	// Test with non-NotFoundError
	regularErr := errors.New("some other error")
	if CodeOf(regularErr) != -1 {
		t.Errorf("Expected -1 for regular error, got %d", CodeOf(regularErr))
	}
}

