func TestParseQuery(t *testing.T) {
	tests := []struct {
		name string
		q    string
		want map[string][]string
	}{
		{
			name: "basic parsing",
			q:    "a=1&b=2&a=3",
			want: map[string][]string{"a": {"1", "3"}, "b": {"2"}},
		},
		{
			name: "empty string",
			q:    "",
			want: map[string][]string{},
		},
		{
			name: "no equals sign",
			q:    "a&b=1",
			want: map[string][]string{"b": {"1"}},
		},
		{
			name: "empty key",
			q:    "=1&a=2",
			want: map[string][]string{"a": {"2"}},
		},
		{
			name: "empty value",
			q:    "a=&b=1",
			want: map[string][]string{"a": {""}, "b": {"1"}},
		},
		{
			name: "multiple empty pairs",
			q:    "&a=1&&b=2&",
			want: map[string][]string{"a": {"1"}, "b": {"2"}},
		},
		{
			name: "single pair",
			q:    "key=value",
			want: map[string][]string{"key": {"value"}},
		},
		{
			name: "duplicate keys",
			q:    "a=1&a=2&a=3",
			want: map[string][]string{"a": {"1", "2", "3"}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := ParseQuery(tt.q)
			if len(got) != len(tt.want) {
				t.Errorf("ParseQuery() got %d keys, want %d", len(got), len(tt.want))
				return
			}
			for k, v := range tt.want {
				gotV, exists := got[k]
				if !exists {
					t.Errorf("ParseQuery() missing key %q", k)
					continue
				}
				if len(gotV) != len(v) {
					t.Errorf("ParseQuery() key %q got %d values, want %d", k, len(gotV), len(v))
					continue
				}
				for i, val := range v {
					if gotV[i] != val {
						t.Errorf("ParseQuery() key %q[%d] got %q, want %q", k, i, gotV[i], val)
					}
				}
			}
		})
	}
}

