import "testing"

func Filter[T any](s []T, keep func(T) bool) []T {
	var result []T
	for _, v := range s {
		if keep(v) {
			result = append(result, v)
		}
	}
	return result
}

func TestFilter(t *testing.T) {
	// Test with integers
	nums := []int{1, 2, 3, 4, 5}
	evens := Filter(nums, func(n int) bool { return n%2 == 0 })
	expected := []int{2, 4}
	if len(evens) != len(expected) {
		t.Errorf("Expected %d elements, got %d", len(expected), len(evens))
	}
	for i, v := range expected {
		if evens[i] != v {
			t.Errorf("Expected %d at index %d, got %d", v, i, evens[i])
		}
	}

	// Test with strings
	strs := []string{"hello", "world", "go", "programming"}
	long := Filter(strs, func(s string) bool { return len(s) > 4 })
	expectedLong := []string{"hello", "world", "programming"}
	if len(long) != len(expectedLong) {
		t.Errorf("Expected %d elements, got %d", len(expectedLong), len(long))
	}
	for i, v := range expectedLong {
		if long[i] != v {
			t.Errorf("Expected %s at index %d, got %s", v, i, long[i])
		}
	}

	// Test with empty slice
	empty := Filter([]int{}, func(n int) bool { return n > 0 })
	if len(empty) != 0 {
		t.Errorf("Expected empty slice, got %v", empty)
	}

	// Test with all elements kept
	all := Filter([]int{1, 2, 3}, func(n int) bool { return n > 0 })
	expectedAll := []int{1, 2, 3}
	if len(all) != len(expectedAll) {
		t.Errorf("Expected %d elements, got %d", len(expectedAll), len(all))
	}
	for i, v := range expectedAll {
		if all[i] != v {
			t.Errorf("Expected %d at index %d, got %d", v, i, all[i])
		}
	}

	// Test with no elements kept
	none := Filter([]int{1, 2, 3}, func(n int) bool { return n > 10 })
	if len(none) != 0 {
		t.Errorf("Expected empty slice, got %v", none)
	}
}

