func TestCountUntil(t *testing.T) {
	t.Run("returns zero when context is already cancelled", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		cancel()

		ch := make(chan int)
		result := CountUntil(ctx, ch)

		if result != 0 {
			t.Errorf("Expected 0, got %d", result)
		}
	})

	t.Run("returns zero when channel is already closed", func(t *testing.T) {
		ctx := context.Background()
		ch := make(chan int)
		close(ch)

		result := CountUntil(ctx, ch)

		if result != 0 {
			t.Errorf("Expected 0, got %d", result)
		}
	})

	t.Run("counts values until context is cancelled", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		ch := make(chan int)

		go func() {
			ch <- 1
			ch <- 2
			cancel()
			ch <- 3
		}()

		result := CountUntil(ctx, ch)

		if result != 2 {
			t.Errorf("Expected 2, got %d", result)
		}
	})

	t.Run("counts values until channel is closed", func(t *testing.T) {
		ctx := context.Background()
		ch := make(chan int)

		go func() {
			ch <- 1
			ch <- 2
			close(ch)
		}()

		result := CountUntil(ctx, ch)

		if result != 2 {
			t.Errorf("Expected 2, got %d", result)
		}
	})

	t.Run("returns zero when context is cancelled before any values", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		ch := make(chan int)

		go func() {
			cancel()
		}()

		result := CountUntil(ctx, ch)

		if result != 0 {
			t.Errorf("Expected 0, got %d", result)
		}
	})

	t.Run("returns zero when channel is closed before any values", func(t *testing.T) {
		ctx := context.Background()
		ch := make(chan int)

		go func() {
			close(ch)
		}()

		result := CountUntil(ctx, ch)

		if result != 0 {
			t.Errorf("Expected 0, got %d", result)
		}
	})
}

